# Solve 8-queens using backtracking
def solve_n_queens(n=8):
    def is_safe(board, row, col):
        # Check column
        for i in range(row):
            if board[i] == col:
                return False
            # Check diagonals
            if abs(board[i] - col) == abs(i - row):
                return False
        return True

    def backtrack(row):
        if row == n:
            return True
        for col in range(n):
            if is_safe(board, row, col):
                board[row] = col
                if backtrack(row + 1):
                    return True
                board[row] = -1
        return False

    board = [-1] * n
    if backtrack(0):
        return board
    return None

solution = solve_n_queens()
print(solution)

def verify(board):
    n = len(board)
    for i in range(n):
        for j in range(i+1, n):
            if board[i] == board[j]:
                return False, f"Same column at rows {i} and {j}"
            if abs(board[i] - board[j]) == abs(i - j):
                return False, f"Same diagonal at rows {i} and {j}"
    return True, "Valid"

print(verify([0, 4, 7, 5, 2, 6, 1, 3]))

